CREATE PROCEDURE CLAIMS.COMPREHENSIVE_CLAIM_ASSESS (
    IN  P_CLAIM_ID            BIGINT,
    IN  P_TENANT_ID           CHAR(8),
    OUT P_FINAL_DECISION      VARCHAR(30),
    OUT P_CONFIDENCE_SCORE    DECIMAL(5,2),
    OUT P_EXCEPTION_FLAG      CHAR(1)
)
LANGUAGE SQL
MODIFIES SQL DATA
P_COMPREHENSIVE_ASSESS: BEGIN
    DECLARE V_CURRENT_TS        TIMESTAMP DEFAULT CURRENT TIMESTAMP;
    DECLARE V_CUSTOMER_ID       BIGINT;
    DECLARE V_CLAIM_AMOUNT      DECIMAL(15,2);
    DECLARE V_CLAIM_TYPE        VARCHAR(20);
    DECLARE V_CUSTOMER_TIER     VARCHAR(10);
    DECLARE V_LIFETIME_COUNT    INTEGER;
    DECLARE V_AVG_AMOUNT        DECIMAL(15,2);
    DECLARE V_MAX_SELF_AMOUNT   DECIMAL(15,2);
    DECLARE V_PEER_AVG_AMOUNT   DECIMAL(15,2);
    DECLARE V_FRAUD_FLAG        CHAR(1);
    DECLARE V_SCORE             DECIMAL(10,4);
    DECLARE V_SIMILAR_CLAIMS    INTEGER;
    DECLARE V_ESCALATION_NOTE   VARCHAR(200);

    SELECT C.CLAIM_AMOUNT,
           C.CLAIM_TYPE,
           C.CUSTOMER_ID,
           CU.CUSTOMER_TIER,
           (SELECT 'Y'
            FROM FRAUD_WATCHLIST FW
            WHERE FW.CUSTOMER_ID = CU.CUSTOMER_ID
              AND FW.ACTIVE_IND = 'Y'
            FETCH FIRST 1 ROW ONLY
           ) AS FRAUD_INDICATOR
    INTO V_CLAIM_AMOUNT,
         V_CLAIM_TYPE,
         V_CUSTOMER_ID,
         V_CUSTOMER_TIER,
         V_FRAUD_FLAG
    FROM CLAIM          AS C
    INNER JOIN CUSTOMER AS CU
        ON C.CUSTOMER_ID = CU.CUSTOMER_ID
       AND C.TENANT_ID  = CU.TENANT_ID
    WHERE C.CLAIM_ID    = P_CLAIM_ID
      AND C.TENANT_ID   = P_TENANT_ID
      AND C.DELETED_IND = 'N';

    SET V_MAX_SELF_AMOUNT =
        (SELECT COALESCE(MAX(PR.CLAIM_AMOUNT), 0)
         FROM CLAIM PR
         WHERE PR.CUSTOMER_ID = V_CUSTOMER_ID
           AND PR.CLAIM_TYPE  = V_CLAIM_TYPE
           AND PR.CLAIM_ID   <> P_CLAIM_ID
           AND PR.TENANT_ID   = P_TENANT_ID);

    SELECT COUNT(CL.CLAIM_ID),
           AVG(CL.CLAIM_AMOUNT)
    INTO V_LIFETIME_COUNT,
         V_AVG_AMOUNT
    FROM CLAIM CL
    INNER JOIN CUSTOMER_ACCOUNT ACC
        ON CL.CUSTOMER_ID = ACC.CUSTOMER_ID
       AND CL.TENANT_ID   = ACC.TENANT_ID
    WHERE CL.CUSTOMER_ID  = V_CUSTOMER_ID
      AND CL.TENANT_ID    = P_TENANT_ID
      AND CL.STATUS       IN ('APPROVED','PAID')
      AND CL.DELETED_IND  = 'N'
      AND EXISTS (
            SELECT 1
            FROM CLAIM_STATUS_HISTORY SH
            WHERE SH.CLAIM_ID = CL.CLAIM_ID
              AND SH.STATUS = 'APPROVED'
              AND SH.CREATED_TS >= CURRENT TIMESTAMP - 2 YEARS
          );

    SELECT AVG(PS.PEER_AMOUNT)
    INTO V_PEER_AVG_AMOUNT
    FROM (
        SELECT CLM.CLAIM_AMOUNT AS PEER_AMOUNT,
               CLM.CUSTOMER_ID,
               ROW_NUMBER() OVER (PARTITION BY CLM.CLAIM_TYPE
                                  ORDER BY CLM.CLAIM_AMOUNT DESC) AS RN
        FROM CLAIM CLM
        WHERE CLM.CLAIM_TYPE   = V_CLAIM_TYPE
          AND CLM.STATUS       IN ('APPROVED','PAID')
          AND CLM.DELETED_IND  = 'N'
          AND CLM.TENANT_ID   <> 'EXCLUDED'
    ) AS PS
    INNER JOIN CUSTOMER PCU
        ON PS.CUSTOMER_ID = PCU.CUSTOMER_ID
    WHERE PCU.CUSTOMER_TIER = V_CUSTOMER_TIER
      AND PS.RN <= 20;

    SELECT COALESCE(W.BASE_WEIGHT, 1.0)
           * (SELECT COALESCE(VALUE, 1.0)
              FROM SYSTEM_CONFIG
              WHERE CONFIG_KEY = 'RISK_MULTIPLIER'
                AND ACTIVE_IND = 'Y')
    INTO V_SCORE
    FROM RISK_FACTOR_WEIGHTS W
    CROSS JOIN (SELECT 1 AS DUMMY FROM SYSIBM.SYSDUMMY1) D
    WHERE W.CLAIM_TYPE    = V_CLAIM_TYPE
      AND W.CUSTOMER_TIER = V_CUSTOMER_TIER;

    SET V_SCORE = V_SCORE +
        (V_CLAIM_AMOUNT / NULLIF(V_PEER_AVG_AMOUNT, 0)) * 40.0 +
        (V_LIFETIME_COUNT * 0.5) +
        (CASE WHEN V_MAX_SELF_AMOUNT > 0
              THEN V_CLAIM_AMOUNT / V_MAX_SELF_AMOUNT * 30.0
              ELSE 0 END);

    SET V_ESCALATION_NOTE =
        (SELECT LISTAGG(ESC.REASON, ', ') WITHIN GROUP (ORDER BY ESC.PRIORITY)
         FROM ESCALATION_TRIGGERS ESC
         WHERE ESC.CLAIM_TYPE = V_CLAIM_TYPE
           AND ESC.THRESHOLD <= V_SCORE
           AND ESC.TENANT_ID  = P_TENANT_ID);

    SET P_CONFIDENCE_SCORE = DECIMAL(ROUND(V_SCORE, 2), 5, 2);

    IF V_FRAUD_FLAG = 'Y' THEN
        SET P_FINAL_DECISION = 'REJECTED_FRAUD';
        SET P_EXCEPTION_FLAG = 'Y';
    ELSEIF P_CONFIDENCE_SCORE > 90.0
           AND NOT EXISTS (SELECT 1 FROM OVERRIDE_AUTHORIZATIONS OV
                           WHERE OV.CLAIM_ID = P_CLAIM_ID
                             AND OV.TENANT_ID = P_TENANT_ID
                             AND OV.APPROVED = 'Y') THEN
        SET P_FINAL_DECISION = 'REJECTED_HIGH_RISK';
        SET P_EXCEPTION_FLAG = 'Y';
    ELSEIF P_CONFIDENCE_SCORE > 75.0 THEN
        SET P_FINAL_DECISION = 'MANUAL_REVIEW';
        SET P_EXCEPTION_FLAG = 'N';
    ELSEIF V_LIFETIME_COUNT >= 10 AND V_AVG_AMOUNT > 5000
           AND (SELECT COUNT(*) FROM CLAIM_DOCUMENT DOC
                WHERE DOC.CLAIM_ID = P_CLAIM_ID
                  AND DOC.TENANT_ID = P_TENANT_ID
                  AND DOC.STATUS = 'VERIFIED') >= 2 THEN
        SET P_FINAL_DECISION = 'APPROVED_WITH_MONITORING';
        SET P_EXCEPTION_FLAG = 'N';
    ELSE
        SET P_FINAL_DECISION = 'APPROVED';
        SET P_EXCEPTION_FLAG = 'N';
    END IF;

END P_COMPREHENSIVE_ASSESS
